package in.aicon.pocket;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import org.json.*;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class BackupFlowTest {
 public static class SynchronousActivity extends QuickActivity {@Override void cryptoWork(Work work){try{work.run();}catch(Exception e){throw new IllegalArgumentException(e);}}}
 SynchronousActivity activity;
 @Before public void setup(){try{androidx.work.WorkManager.getInstance(RuntimeEnvironment.getApplication());}catch(IllegalStateException init){androidx.work.WorkManager.initialize(RuntimeEnvironment.getApplication(),new androidx.work.Configuration.Builder().setMinimumLoggingLevel(android.util.Log.ERROR).build());}RuntimeEnvironment.getApplication().deleteDatabase("pocket.db");activity=Robolectric.buildActivity(SynchronousActivity.class).setup().get();}
 @After public void close(){activity.onDestroy();}
 EditText field(View v,String hint){if(v instanceof EditText&&hint.equals(((EditText)v).getHint().toString()))return(EditText)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){EditText found=field(((ViewGroup)v).getChildAt(n),hint);if(found!=null)return found;}return null;}
 byte[] backup()throws Exception{byte[] salt=new byte[16],iv=new byte[12];java.util.Arrays.fill(salt,(byte)7);java.util.Arrays.fill(iv,(byte)9);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,activity.key("testing-only-passphrase",salt),new GCMParameterSpec(128,iv));cipher.updateAAD("hisab-v1".getBytes(StandardCharsets.UTF_8));return new JSONObject().put("format","hisab").put("version",1).put("iterations",210000).put("salt",activity.enc(salt)).put("iv",activity.enc(iv)).put("data",activity.enc(cipher.doFinal(activity.data()))).toString().getBytes(StandardCharsets.UTF_8);}
 void unlock(byte[] bytes){activity.restorePass(bytes);AlertDialog form=activity.activeForm;field(form.getWindow().getDecorView(),"Backup passphrase").setText("testing-only-passphrase");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();form.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void encryptedBackupExportLimitMatchesRestoreLimit(){assertTrue(MainActivity.backupFitsRestoreLimit(new byte[MainActivity.MAX_BACKUP_BYTES]));assertFalse(MainActivity.backupFitsRestoreLimit(new byte[MainActivity.MAX_BACKUP_BYTES+1]));assertFalse(MainActivity.backupFitsRestoreLimit(null));}
 @Test public void decryptReachesReplacementConfirmationWithoutMutatingLedgerVersion()throws Exception{activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));Object current=activity.replacementTicket();unlock(backup());assertTrue(activity.actionCurrent(current));AlertDialog confirmation=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotSame(activity.activeForm,confirmation);confirmation.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals(1,activity.sum("SELECT count(*) FROM tx"));}
 @Test public void decryptedReplacementCannotOverwriteInterveningNewEntry()throws Exception{activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));unlock(backup());AlertDialog confirmation=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",500,"",""));confirmation.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(2,activity.sum("SELECT count(*) FROM tx"));}
 @Test public void encryptedBackupPassphraseFormDoesNotWriteOrInvalidateLedger()throws Exception{Object current=activity.replacementTicket();activity.backup();AlertDialog form=activity.activeForm;field(form.getWindow().getDecorView(),"At least 8 characters").setText("testing-only-passphrase");field(form.getWindow().getDecorView(),"Repeat passphrase").setText("testing-only-passphrase");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();form.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(activity.actionCurrent(current));assertNotNull(activity.pending);assertTrue(activity.actionCurrent(activity.fileAction));JSONObject encrypted=new JSONObject(new String(activity.pending,StandardCharsets.UTF_8));assertEquals("hisab",encrypted.getString("format"));assertFalse(encrypted.has("tx"));}
}
